import React from "react";
import { AbsoluteFill, OffthreadVideo, Sequence, staticFile, useCurrentFrame } from "remotion";
import { loadFont } from "@remotion/fonts";
import raw from "./edl.json";
import { Grain } from "../signal/kit";

// Baul riverbank music video — Rapar Rubel.
//
// Edited from the artist's eight AI clips (a Baul singer with a dotara on a
// riverbank, day → sunset → night) to the artist's song. The edit decision
// list is generated by client-builds/baul-mv/edl.py: cuts on detected
// downbeats, pacing per section, chorus triptychs, the day-to-night
// time-lapse over the breakdown. This file only renders it.
//
// 16:9 master: vertical shots sit framed over a blurred, graded copy of
// themselves; chorus triptychs fill the width with three shots. The vertical
// cut (BaulMVVertical) plays the same edit full-frame at 9:16.

type Shot = { id: number; clip: number; in: number; rate: number; flip: boolean; z0: number; z1: number; dx: number };
type Ev = { s: number; e: number; layout: "single" | "tri"; trans: "cut" | "xfade" | "flash"; shots: Shot[] };
const D = raw as unknown as { fps: number; duration: number; frames: number; beats: number[]; downbeats: number[]; rms: number[]; events: Ev[] };
export const BAUL_FRAMES = D.frames;
const FPS = D.fps;
const XF = 0.8; // cross-dissolve seconds

const SERIF = "BaulSerif";
loadFont({ family: SERIF, url: staticFile("baul/NotoSerifDisplay-Regular.ttf"), weight: "400" });
loadFont({ family: SERIF, url: staticFile("baul/NotoSerifDisplay-Italic.ttf"), weight: "400", style: "italic" });

const clamp = (v: number, a = 0, b = 1) => Math.min(b, Math.max(a, v));
const smooth = (t: number) => { const x = clamp(t); return x * x * (3 - 2 * x); };
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const lastIndex = (arr: number[], t: number) => { let lo = 0, hi = arr.length - 1, r = -1; while (lo <= hi) { const m = (lo + hi) >> 1; if (arr[m] <= t) { r = m; lo = m + 1; } else hi = m - 1; } return r; };
const downPulse = (t: number, k = 5) => { const i = lastIndex(D.downbeats, t); return i < 0 ? 0 : Math.exp(-(t - D.downbeats[i]) * k); };

// warm, slightly lifted grade shared by every shot
const GRADE = "contrast(1.07) saturate(1.12) brightness(1.02)";

const Clip: React.FC<{ sh: Shot; ev: Ev; w: number; h: number; blur?: boolean }> = ({ sh, ev, w, h, blur }) => {
  const f = useCurrentFrame();                       // local to the event's Sequence
  const k = clamp(f / ((ev.e - ev.s) * FPS));
  const z = lerp(sh.z0, sh.z1, smooth(k)) * (blur ? 1.15 : 1);
  const dx = sh.dx * k * 100;
  return (
    <div style={{ position: "absolute", inset: 0, overflow: "hidden", width: w, height: h }}>
      <OffthreadVideo src={staticFile(`baul/c${sh.clip}.mp4`)} muted startFrom={Math.round(sh.in * FPS)} playbackRate={sh.rate}
        style={{ width: "100%", height: "100%", objectFit: "cover",
          transform: `scale(${z}) translateX(${dx}%) scaleX(${sh.flip ? -1 : 1})`,
          filter: blur ? "blur(26px) brightness(0.68) saturate(1.45)" : GRADE }} />
    </div>
  );
};

const Layout: React.FC<{ ev: Ev; vertical: boolean }> = ({ ev, vertical }) => {
  const f = useCurrentFrame();
  const local = f / FPS;
  const fadeIn = ev.trans === "xfade" ? smooth(local / XF) : 1;
  const punch = ev.trans === "flash" ? 1 + 0.06 * Math.exp(-local * 9) : 1;
  const W = vertical ? 1080 : 1920, Hh = vertical ? 1920 : 1080;
  let body: React.ReactNode;
  if (ev.layout === "tri") {
    body = vertical
      ? ev.shots.map((sh, i) => (
        <div key={i} style={{ position: "absolute", left: 0, top: i * 640, width: 1080, height: 640, overflow: "hidden", borderBottom: i < 2 ? "6px solid #0b0806" : undefined }}>
          <Clip sh={sh} ev={ev} w={1080} h={640} />
        </div>))
      : ev.shots.map((sh, i) => (
        <div key={i} style={{ position: "absolute", left: i * 640, top: 0, width: 640, height: 1080, overflow: "hidden", borderRight: i < 2 ? "6px solid #0b0806" : undefined,
          transform: `translateY(${(1 - smooth(local / 0.25)) * (i % 2 ? -60 : 60)}px)` }}>
          <Clip sh={sh} ev={ev} w={640} h={1080} />
        </div>));
  } else if (vertical) {
    body = <Clip sh={ev.shots[0]} ev={ev} w={1080} h={1920} />;
  } else {
    const pw = 608;
    body = (
      <>
        <Clip sh={ev.shots[0]} ev={ev} w={1920} h={1080} blur />
        <div style={{ position: "absolute", left: (1920 - pw) / 2, top: 0, width: pw, height: 1080, overflow: "hidden",
          boxShadow: "0 0 80px rgba(0,0,0,0.65)", outline: "2px solid rgba(255,220,170,0.25)" }}>
          <Clip sh={ev.shots[0]} ev={ev} w={pw} h={1080} />
        </div>
      </>
    );
  }
  return <AbsoluteFill style={{ opacity: fadeIn, transform: `scale(${punch})`, width: W, height: Hh }}>{body}</AbsoluteFill>;
};

const Titles: React.FC<{ t: number; vertical: boolean }> = ({ t, vertical }) => {
  const open = smooth((t - 0.8) / 1.4) * (1 - smooth((t - 6.2) / 1.0));
  const endIn = smooth((t - (D.duration - 13)) / 1.5);
  const mark = smooth((t - 8) / 1.5) * (1 - endIn);
  const sz = vertical ? 0.8 : 1;
  return (
    <>
      {open > 0.001 && (
        <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", opacity: open }}>
          <div style={{ fontFamily: SERIF, fontStyle: "italic", fontSize: 40 * sz, color: "#F3E2C4", letterSpacing: 6, textShadow: "0 2px 18px rgba(0,0,0,0.8)" }}>a film by</div>
          <div style={{ fontFamily: SERIF, fontSize: 150 * sz, color: "#FFF4E2", letterSpacing: 18 * sz, lineHeight: 1.1, textShadow: "0 4px 40px rgba(0,0,0,0.85)",
            transform: `scale(${lerp(1.06, 1, smooth((t - 0.8) / 5))})` }}>RAPAR RUBEL</div>
          <div style={{ width: 380 * sz, height: 2, background: "linear-gradient(90deg, transparent, #E8B76A, transparent)", marginTop: 18 }} />
        </AbsoluteFill>
      )}
      {mark > 0.001 && (
        <div style={{ position: "absolute", right: vertical ? 40 : 56, top: vertical ? 60 : 44, opacity: 0.72 * mark, fontFamily: SERIF, fontSize: 30, letterSpacing: 8,
          color: "#FFF4E2", textShadow: "0 2px 10px rgba(0,0,0,0.8)" }}>RAPAR RUBEL</div>
      )}
      {endIn > 0.001 && (
        <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", opacity: endIn * (1 - smooth((t - (D.duration - 1.6)) / 1.4)),
          background: `rgba(0,0,0,${0.35 * endIn})` }}>
          <div style={{ fontFamily: SERIF, fontStyle: "italic", fontSize: 38 * sz, color: "#F3E2C4", letterSpacing: 4 }}>Music Video by</div>
          <div style={{ fontFamily: SERIF, fontSize: 120 * sz, color: "#FFF4E2", letterSpacing: 14 * sz, lineHeight: 1.15, textShadow: "0 4px 40px rgba(0,0,0,0.85)" }}>RAPAR RUBEL</div>
          <div style={{ fontFamily: SERIF, fontSize: 44 * sz, color: "#E8B76A", letterSpacing: 6, marginTop: 6 }}>( Rubel Miah )</div>
        </AbsoluteFill>
      )}
    </>
  );
};

export const BaulMV: React.FC<{ vertical?: boolean }> = ({ vertical = false }) => {
  const f = useCurrentFrame();
  const t = f / FPS;
  const evs = D.events;
  const flash = evs.reduce((m, ev) => (ev.trans === "flash" && t >= ev.s ? Math.max(m, Math.exp(-(t - ev.s) * 16)) : m), 0);
  const warm = clamp((t - 85) / 30) * (1 - clamp((t - 205) / 12));       // sunset section glows warmer
  const night = clamp((t - 205) / 12);
  return (
    <AbsoluteFill style={{ background: "#000" }}>
      {evs.map((ev, i) => {
        const nxt = evs[i + 1];
        const tail = nxt && nxt.trans === "xfade" ? XF : 0;
        const from = Math.round(ev.s * FPS), to = Math.round((ev.e + tail) * FPS);
        return (
          <Sequence key={i} from={from} durationInFrames={Math.max(1, to - from)}>
            <Layout ev={ev} vertical={vertical} />
          </Sequence>
        );
      })}
      {/* grade: warm highlights by day, amber glow at sunset, cool blue at night */}
      <AbsoluteFill style={{ mixBlendMode: "soft-light", background: `linear-gradient(180deg, rgba(255,170,90,${0.22 + warm * 0.25}) 0%, rgba(30,60,90,${0.18 + night * 0.25}) 100%)` }} />
      <AbsoluteFill style={{ mixBlendMode: "screen", opacity: 0.14 * warm + 0.1 * downPulse(t) * warm,
        background: "radial-gradient(ellipse 60% 50% at 70% 20%, rgba(255,150,60,0.8), rgba(255,150,60,0) 70%)" }} />
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at center, rgba(0,0,0,0) 55%, rgba(0,0,0,0.55) 100%)" }} />
      <Grain frame={f} opacity={0.12} />
      {flash > 0.01 && <AbsoluteFill style={{ background: "#FFF6E8", opacity: flash * 0.55 }} />}
      <Titles t={t} vertical={vertical} />
      <AbsoluteFill style={{ background: "#000", opacity: 1 - smooth(t / 1.2) }} />
    </AbsoluteFill>
  );
};

export const BaulMVVertical: React.FC = () => <BaulMV vertical />;
